def forward(
    self,
    layer: AttentionLayer,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    kv_cache: tuple[torch.Tensor],
    attn_metadata: AscendMetadata,
    output: torch.Tensor | None = None,
    output_scale: torch.Tensor | None = None,
    output_block_scale: torch.Tensor | None = None,
) -> torch.Tensor:
    assert output is not None, "Output tensor must be provided."

    if output_scale is not None or output_block_scale is not None:
        raise NotImplementedError("fused output quantization is not yet supported for AscendC8AttentionBackendImpl")

    num_tokens = query.shape[0]
    if attn_metadata is None:
        return output.fill_(0)

    self._prepare_c8_scales(layer, query.device)
    float_key, float_value = None, None
    if self.vllm_config.kv_transfer_config is None:
        if key is not None and value is not None:
            if attn_metadata.attn_state != AscendAttentionState.DecodeOnly:
                float_key, float_value = key, value
            key, value = self._quantize_kv_to_int8(key, value, layer, attn_metadata.num_actual_tokens)
            query, key, value, _ = self._reshape_and_cache(query, key, value, kv_cache, attn_metadata, output)
        # pooling model branch
        if attn_metadata.model_runner_type == "pooling":
            attn_output = self._forward_encoder_attention(query, key, value, attn_metadata, output)
            output[:num_tokens] = attn_output[:num_tokens]
            return output
        if attn_metadata.attn_state == AscendAttentionState.DecodeOnly:
            if _EXTRA_CTX.capturing:
                attn_output, num_tokens = self.full_graph_fia(query, key, value, attn_metadata, output, layer)
                output[:num_tokens] = attn_output[:num_tokens]
                return output
            return self._forward_c8_decode(query, attn_metadata, output, layer)
        elif attn_metadata.attn_state == AscendAttentionState.ChunkedPrefill:
            return self._forward_c8_chunked_prefill(query, float_key, float_value, attn_metadata, output, layer)
        else:
            return self._forward_c8_fused_infer_attention(
                query,
                float_key if float_key is not None else key,
                float_value if float_value is not None else value,
                attn_metadata,
                output,
                layer,
            )
    else:
        if attn_metadata.attn_state != AscendAttentionState.DecodeOnly and self.is_kv_producer:
            output_padded = None
            if key is not None and value is not None:
                output_padded = output
                query, key, value, output_padded = self.reshape_and_cache(
                    query, key, value, kv_cache, attn_metadata, output
                )
            # pooling model branch
            if attn_metadata.model_runner_type == "pooling":
                attn_output = self._forward_encoder_attention(query, key, value, attn_metadata, output)
                output[:num_tokens] = attn_output[:num_tokens]
                return output
            if output_padded is not None:
                attn_output = self.forward_impl(query, key, value, kv_cache, attn_metadata, output_padded)
            else:
                attn_output = self.forward_impl(query, key, value, kv_cache, attn_metadata, output)
            output[:num_tokens] = attn_output[:num_tokens]
            return output
        elif not self.is_kv_producer:
            if key is not None and value is not None:
                key, value = self._quantize_kv_to_int8(key, value, layer, attn_metadata.num_actual_tokens)
                query, key, value, _ = self._reshape_and_cache(query, key, value, kv_cache, attn_metadata, output)
            # pooling model branch
            if attn_metadata.model_runner_type == "pooling":
                attn_output = self._forward_encoder_attention(query, key, value, attn_metadata, output)
                output[:num_tokens] = attn_output[:num_tokens]
                return output
            if _EXTRA_CTX.capturing:
                attn_output, num_tokens = self.full_graph_fia(query, key, value, attn_metadata, output, layer)
                output[:num_tokens] = attn_output[:num_tokens]
                return output
            elif attn_metadata.attn_state == AscendAttentionState.DecodeOnly:
                return self._forward_c8_decode(query, attn_metadata, output, layer)

def reshape_and_cache(cls, key, value, key_cache, value_cache, slot_mapping):
    torch_npu._npu_reshape_and_cache(
        key=key, value=value, key_cache=key_cache, value_cache=value_cache, slot_indices=slot_mapping
    )

def profile(self, is_start: bool = True, profile_prefix: str | None = None):
    # Check if profiling is enabled (RFC #6954 - align with upstream vLLM)
    if self.profiler_config is None or self.profiler_config.profiler is None:
        raise RuntimeError(
            "Profiling is not enabled. Please set --profiler-config to enable "
            "profiling. Example: "
            "'--profiler-config.profiler=torch --profiler-config.torch_profiler_dir"
            "=YOUR_DIR_PATH_TO_DUMP_TRACE'"
        )

    if is_start:
        from vllm.distributed.utils import get_worker_rank_suffix

        rank_suffix = get_worker_rank_suffix(global_rank=self.rank)
        trace_name = f"{profile_prefix}_{rank_suffix}" if profile_prefix else rank_suffix

        if self.profiler is None:
            self.profiler = TorchNPUProfilerWrapper(self.profiler_config, trace_name)
            logger.debug("Starting torch profiler with trace name: %s", trace_name)
            self.profiler.start()  # type: ignore[attr-defined]
        else:
            # Profiler already initialized. Restart profiling but keep
            # the original trace name from the first initialization.
            self.profiler.start()
    else:
        if self.profiler is None:
            logger.warning("Profiler was not started, nothing to stop.")
            return
        self.profiler.stop()

def start(self) -> None:
    """Attempt to start the profiler, accounting for delayed starts."""
    if self._active:
        logger.debug(
            "start_profile received when profiler is already active. "
            "Ignoring request."
        )
        return
    self._active = True
    if self._delay_iters == 0:
        self._call_start()

def stop(self) -> None:
    """Attempt to stop the profiler, accounting for overlapped calls."""
    if not self._active:
        logger.debug(
            "stop_profile received when profiler is not active. Ignoring request."
        )
        return
    self._active = False
    self._active_iteration_count = 0
    self._profiling_for_iters = 0

    if self._running:
        self._call_stop()
